#include <stdio.h>

int main(void) {
    int a = 7, b = 3;
    unsigned flags = 5u;
    unsigned mask = 2u;
    printf("division=%d remainder=%d\n", a / b, a % b);
    printf("range=%d\n", 0 <= a && a <= 10);
    printf("AND=%u OR=%u XOR=%u\n", flags & mask, flags | mask, flags ^ mask);
    int old = a++;
    printf("old=%d now=%d max=%d\n", old, a, a > b ? a : b);
    return 0;
}
